def process(climateMeasurements) -> pd.DataFrame:
    import pandas as pd
    import numpy as np

    df = climateMeasurements.copy()

    # Find the first row that looks like a header row (contains 'dust' in any cell)
    header_idx = None
    for i in range(min(len(df), 200)):
        row = df.iloc[i].astype(str).str.lower()
        if row.str.contains('dust').any() and row.str.contains('ppm').any():
            header_idx = i
            break
    if header_idx is None:
        # fallback: use the first non-empty row after metadata where the first col equals 'Site'
        for i in range(min(len(df), 400)):
            row = df.iloc[i].astype(str).str.strip().str.lower()
            if (row == 'site').any():
                header_idx = i
                break

    if header_idx is None:
        # If still not found, return diagnostic
        return pd.DataFrame([{
            'error': 'Could not locate header row',
            'nrows': len(df),
            'ncols': df.shape[1]
        }])

    # Build header
    header = df.iloc[header_idx].astype(str).str.strip()
    data = df.iloc[header_idx + 1:].copy()
    data.columns = header

    # Drop completely empty columns
    data = data.dropna(axis=1, how='all')

    # Normalize column names
    def norm(s: str) -> str:
        return ' '.join(str(s).strip().lower().split())

    colmap = {c: norm(c) for c in data.columns}
    data = data.rename(columns=colmap)

    # Identify key columns
    dust_col = None
    wetdry_col = None
    ca_col = None

    for c in data.columns:
        if dust_col is None and ('dust' in c and 'proxy' in c):
            dust_col = c
        if wetdry_col is None and ('wet' in c and 'dry' in c and 'index' in c):
            wetdry_col = c
        # calcium column: contains 'ca' and 'ppm' or 'calcium'
        if ca_col is None and (('calcium' in c) or (c.startswith('ca') and 'ppm' in c) or (' ca ' in f' {c} ' and 'ppm' in c)):
            ca_col = c

    # Fallbacks if not found
    if dust_col is None:
        for c in data.columns:
            if 'dust' in c:
                dust_col = c
                break
    if ca_col is None:
        for c in data.columns:
            if 'ppm' in c and ('ca' in c or 'calcium' in c):
                ca_col = c
                break

    if wetdry_col is None or dust_col is None or ca_col is None:
        return pd.DataFrame([{
            'header_row_index': header_idx,
            'dust_col_found': dust_col,
            'wetdry_col_found': wetdry_col,
            'ca_col_found': ca_col,
            'ncols_after': data.shape[1],
            'sample_cols': ', '.join(list(data.columns)[:25])
        }])

    out = data[[dust_col, wetdry_col, ca_col]].copy()
    out = out.rename(columns={dust_col: 'dustProxy', wetdry_col: 'wetDryIndex', ca_col: 'calciumPpm'})

    # Coerce numeric
    for c in ['dustProxy', 'wetDryIndex', 'calciumPpm']:
        out[c] = pd.to_numeric(out[c], errors='coerce')

    out = out.dropna(subset=['dustProxy', 'wetDryIndex', 'calciumPpm'])
    return out.reset_index(drop=True)
